#!/usr/bin/env python3
"""Second demonstration: convergence rates, the Catalan defect, and the guards.

This script measures, in exact rational arithmetic, *how* the two draw laws
approach the universal constant 6/7, and checks every proved guard numerically:

  * the balanced deficit  6/7 - rho^2_max(B_v)  against the proved lower guard
    1/(15(v+1)) and against its empirical rate  0.0262/v;
  * the uniform excess  rho^2_max(D_b) - 6/7  against 4^-b;
  * the draw-law gap  rho^2_max(D_{2v+2}) - rho^2_max(B_v)  against the proved
    envelope  1/(15(v+1)) + 4^{-(2v+2)};
  * the Catalan identity  2 m_1 - m_0 = Cat_v  and the relative defect 1/(2v+1);
  * the sparse-side gap along r = v+2 against the proved bound 1/(7(2v+3))
    and against its empirical limit 54/343.

Run:  python3 demo2.py
"""

from __future__ import annotations

from fractions import Fraction
from math import comb
from typing import List

SIX_SEVENTHS = Fraction(6, 7)


def ceiling(profile: List[int]) -> Fraction:
    n = sum(profile)
    return Fraction(1) - Fraction(sum(m ** 3 for m in profile) - n, n ** 3 - n)


def hockey_stick_vr(v: int, r: int) -> List[int]:
    return [comb(v + r - k, v) for k in range(r + 1)]


def balanced(v: int) -> List[int]:
    return hockey_stick_vr(v, v + 1)


def dyadic_closed_form(b: int) -> Fraction:
    n = 2 ** b
    return SIX_SEVENTHS * (1 + Fraction(1, n * (n + 1)))


def catalan(v: int) -> int:
    return comb(2 * v, v) // (v + 1)


def rule(title: str) -> None:
    print("\n" + title)
    print("-" * len(title))


def main() -> None:
    rule("A.  Balanced deficit versus the proved guard 1/(15(v+1))")
    print("      v |   6/7 - rho^2      |   1/(15(v+1))    | guard holds |  v * deficit")
    for v in (2, 5, 10, 50, 200, 800):
        deficit = SIX_SEVENTHS - ceiling(balanced(v))
        guard = Fraction(1, 15 * (v + 1))
        print(f"  {v:6d} |  {float(deficit):.12f}  |  {float(guard):.12f}  |    "
              f"{deficit < guard!s:<5}    |   {float(v * deficit):.6f}")

    rule("B.  Uniform excess versus 4^-b (exponential convergence from above)")
    print("      b |  rho^2 - 6/7       |   4^-b")
    for b in (4, 8, 16, 32, 60):
        excess = dyadic_closed_form(b) - SIX_SEVENTHS
        print(f"  {b:6d} |  {float(excess):.6e}      |  {float(Fraction(1, 4 ** b)):.6e}")

    rule("C.  Draw-law gap versus the proved envelope 1/(15(v+1)) + 4^-(2v+2)")
    print("      v | bitlen |   uniform - balanced |   envelope        | holds")
    for v in (2, 5, 10, 29, 94):
        gap = dyadic_closed_form(2 * v + 2) - ceiling(balanced(v))
        env = Fraction(1, 15 * (v + 1)) + Fraction(1, 4 ** (2 * v + 2))
        print(f"  {v:6d} | {2*v+2:6d} |   {float(gap):.12f}   |  {float(env):.12f}  | {gap < env}")

    rule("D.  The Catalan defect of the first step")
    print("      v |     m_0      |     m_1      | 2m_1 - m_0 |  Cat_v  | relative defect 1/(2v+1)")
    for v in range(1, 10):
        prof = balanced(v)
        m0, m1 = prof[0], prof[1]
        print(f"  {v:6d} | {m0:12d} | {m1:12d} | {2*m1-m0:10d} | {catalan(v):7d} | "
              f"{Fraction(2*m1-m0, m0)} = {float(Fraction(1, 2*v+1)):.6f}")

    rule("E.  Sparse side along r = v+2: gap versus the proved bound 1/(7(2v+3))")
    print("      v |  rho^2 - 6/7       |  1/(7(2v+3))      | holds |  v * gap  (limit 54/343 = "
          f"{float(Fraction(54,343)):.6f})")
    for v in (1, 5, 20, 100, 400):
        gap = ceiling(hockey_stick_vr(v, v + 2)) - SIX_SEVENTHS
        bound = Fraction(1, 7 * (2 * v + 3))
        print(f"  {v:6d} |  {float(gap):.12f}  |  {float(bound):.12f}   | {bound < gap!s:<5} |"
              f"  {float(v * gap):.6f}")

    rule("F.  Imbalance robustness: the 0.73 guard on weight fractions in [1/2, 3/5]")
    print("   bitlen |  weight |  theta  |  rho^2_max     | above 0.73 | band 0.85^2 admissible")
    for b in (20, 40, 60, 100):
        for theta_num, theta_den in ((1, 2), (11, 20), (3, 5)):
            w = (b * theta_num) // theta_den
            prof = [comb(b - 1 - k, w - 1) for k in range(b - w + 1)]
            c = ceiling(prof)
            print(f"  {b:7d} | {w:7d} |  {w/b:.3f}  |  {float(c):.10f}  |   "
                  f"{c > Fraction(73,100)!s:<5}    |  {Fraction(85,100)**2 < c}")

    print("\nAll rate checks completed in exact rational arithmetic.")


if __name__ == "__main__":
    main()

