"""Algorithm A — exact evaluation of the tie ceiling of a rank statistic.

Given the tie profile m = (m_0, ..., m_k) of a statistic on n observations, the
maximal squared Spearman correlation attainable against any response is

    rho^2_max(m) = 1 - (sum_j m_j^3 - n) / (n^3 - n).

Everything is done in exact rational arithmetic so that comparisons against
constants such as 6/7 are decisions, not floating-point guesses.
"""

from __future__ import annotations

from fractions import Fraction
from typing import Iterable, List, Sequence, Tuple


def tie_correction(profile: Sequence[int]) -> Fraction:
    """Classical Spearman tie correction T = sum_j (m_j^3 - m_j) / 12."""
    return Fraction(sum(m ** 3 - m for m in profile), 12)


def tie_ceiling(profile: Sequence[int]) -> Fraction:
    """Exact rho^2_max of a tie profile.  Cost: O(k) big-integer cubes."""
    n = sum(profile)
    if n < 2:
        raise ValueError("the ceiling requires n >= 2 observations")
    return Fraction(1) - Fraction(12, 1) * tie_correction(profile) / Fraction(n ** 3 - n, 1)


def max_correlation(profile: Sequence[int]) -> float:
    """The attainable |rho| itself, as a float."""
    c = tie_ceiling(profile)
    return float(c) ** 0.5


def compare_to(profile: Sequence[int], target: Fraction) -> int:
    """Exact three-way comparison of the ceiling against a rational target.

    Returns -1, 0 or +1 according as rho^2_max is below, equal to, or above the
    target.  No floating point is involved anywhere.
    """
    c = tie_ceiling(profile)
    return (c > target) - (c < target)


def ceiling_report(profile: Sequence[int]) -> Tuple[int, Fraction, float]:
    """(sample size, exact ceiling, attainable |rho|)."""
    return sum(profile), tie_ceiling(profile), max_correlation(profile)


if __name__ == "__main__":
    for prof in ([3, 2, 1], [4, 3, 2, 1], [10, 6, 3, 1], [12], [1, 1, 1]):
        n, c, r = ceiling_report(prof)
        print(f"{str(prof):<16} n={n:<4} rho^2_max={str(c):<12} |rho| <= {r:.6f} "
              f"sign vs 6/7: {compare_to(prof, Fraction(6, 7)):+d}")

