function SIGN_VS_SIX_SEVENTHS(b, w):
    return COMPARE_TO(HOCKEY_STICK(b, w), 6/7)

function CERTIFY_BOUNDARY(w_max, slack):
    for w from 2 to w_max:
        for b from w+1 to 2w:                 # weight at least half
            assert SIGN_VS_SIX_SEVENTHS(b, w) <= 0
        b_cross <- least b in [w+1, 2w+slack] with sign > 0
        assert b_cross == 2w + 1              # boundary is exactly at 2w = b
    return true
